from rich.console import Console
from rich.prompt import Prompt, InvalidResponse

console = Console(markup=False)

class MyPrompt(Prompt):
    def process_response(self, value):
        if value != "yes":
            raise InvalidResponse("[red]Invalid response![/red]")
        return value

try:
    # We need to simulate user input. Prompt.ask() uses input().
    # Since we are in a script, we can't easily simulate input() without mocking.
    # But we can call process_response and on_validate_error directly.
    prompt = MyPrompt()
    prompt.console = console
    try:
        prompt.process_response("no")
    except InvalidResponse as e:
        prompt.on_validate_error("no", e)
except Exception as e:
    print(f"Error: {e}")
